// Bounded diagnostics of native decks generated by the actual examples/levels/*.tsx.
// Vendor source and complete native decks stay in ignored runs/.
import { readFile, mkdir, writeFile } from 'node:fs/promises'
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'
import { createHash } from 'node:crypto'
import { channelSpice } from '../src/extraction'
import { inspectPins, edgeSeconds } from '../src/buffers/inspect'
import { waveformConvergence } from '../src/observation/convergence'

const exec = promisify(execFile)
const phase = process.argv[2] ?? 'edge'
const input = process.env.SI_INVESTIGATION_INPUT ?? 'runs/rfc-final'
const root = process.env.SI_INVESTIGATION_ROOT ?? 'runs/section-investigation'
const timeout = Number(process.env.SI_NATIVE_TIMEOUT_MS ?? 120000)
const sources = Object.fromEntries(await Promise.all(['sn74lvc1g04.ibs', 'sn65hvd72.ibs'].map(async file => [
  `models/${file}`, await readFile(`${process.env.IBIS_MODEL_DIR ?? 'models'}/${file}`, 'utf8'),
])))
const cases = {}
await mkdir(root, { recursive: true })

function digest(body) {
  return createHash('sha256').update(body).digest('hex')
}

// Positive eigenvalues of LC give squared modal delays. These cases have 1..3 legs.
function eigenvalues(a) {
  if (a.length === 1) return [a[0][0]]
  const trace = a.reduce((sum, row, i) => sum + row[i], 0)
  if (a.length === 2) {
    const delta = Math.sqrt((a[0][0] - a[1][1]) ** 2 + 4 * a[0][1] * a[1][0])
    return [(trace - delta) / 2, (trace + delta) / 2]
  }
  const minors = a.reduce((sum, row, i) => sum + row.slice(i + 1).reduce((s, _, k) => {
    const j = i + k + 1
    return s + a[i][i] * a[j][j] - a[i][j] * a[j][i]
  }, 0), 0)
  const det = a[0].reduce((sum, _, i) => sum + a[0][i] * (a[1][(i + 1) % 3] * a[2][(i + 2) % 3] - a[1][(i + 2) % 3] * a[2][(i + 1) % 3]), 0)
  const p = minors - trace ** 2 / 3
  const q = -2 * trace ** 3 / 27 + trace * minors / 3 - det
  const angle = Math.acos(Math.max(-1, Math.min(1, 3 * q / (2 * p) * Math.sqrt(-3 / p))))
  return [0, 1, 2].map(k => trace / 3 + 2 * Math.sqrt(-p / 3) * Math.cos((angle - 2 * k * Math.PI) / 3))
}

for (const name of ['single', 'differential', 'three']) {
  const circuit = JSON.parse(await readFile(`${input}/${name}/input.json`, 'utf8'))
  const requestFile = `${input}/${name}/native-${name === 'differential' ? 5 : 7}-ngspice/request.json`
  const request = JSON.parse(await readFile(requestFile, 'utf8'))
  const deck = request.files['simulation.cir']
  const channel = deck.match(/\.subckt CHANNEL .*?\.ends CHANNEL/s)[0]
  const n = channel.split('\n')[0].split(' ').filter(token => /^IN\d/.test(token)).length
  const sections = [...channel.matchAll(/^VS\d+_0 /gm)].length
  const matrices = Object.fromEntries(['R', 'L', 'C'].map(kind => [kind, Array.from({ length: n }, () => Array(n).fill(0))]))
  for (let i = 0; i < n; i++) {
    for (const kind of ['R', 'L']) matrices[kind][i][i] = Number(channel.match(new RegExp(`^${kind}0_${i} \\S+ \\S+ (\\S+)`, 'm'))[1]) * sections
    const expression = channel.match(new RegExp(`^E0_${i} .*value=\\{(.*)\\}`, 'm'))?.[1] ?? ''
    for (const term of expression.matchAll(/([\deE.+-]+)\*i\(VS0_(\d+)\)/g)) matrices.R[i][Number(term[2])] = Number(term[1]) * sections
    for (let j = 0; j < n; j++) if (i !== j) {
      const k = Number(channel.match(new RegExp(`^K0_${Math.min(i, j)}_${Math.max(i, j)} \\S+ \\S+ (\\S+)`, 'm'))[1])
      const lj = Number(channel.match(new RegExp(`^L0_${j} \\S+ \\S+ (\\S+)`, 'm'))[1]) * sections
      matrices.L[i][j] = k * Math.sqrt(matrices.L[i][i] * lj)
      const c = Number(channel.match(new RegExp(`^CM0a${Math.min(i, j)}_${Math.max(i, j)} \\S+ \\S+ (\\S+)`, 'm'))?.[1] ?? 0) * sections * 2
      matrices.C[i][j] = -c
      matrices.C[i][i] += c
    }
    matrices.C[i][i] += Number(channel.match(new RegExp(`^CG0a${i} \\S+ \\S+ (\\S+)`, 'm'))[1]) * sections * 2
  }
  const pins = [...inspectPins(circuit, sources).values()].filter(pin => pin.buffer.type !== 'input')
  const edges = pins.map(pin => ({ port: pin.port, model: pin.buffer.name, edge_s: edgeSeconds(pin, 0), waveform_edges: pin.buffer.waveforms.map(waveform => ({
    kind: waveform.kind, fixture_v: waveform.fixtureVoltage[0], resistance_ohm: waveform.resistance,
    edge_s: edgeSeconds({ ...pin, buffer: { ...pin.buffer, waveforms: [waveform] } }, 0),
  })) }))
  const edge = Math.min(...edges.map(item => item.edge_s))
  const length = Math.max(...circuit.filter(record => record.type === 'pcb_trace').map(trace => trace.route.slice(1).reduce((sum, point, i) => sum + Math.hypot(point.x - trace.route[i].x, point.y - trace.route[i].y), 0) / 1000))
  const product = matrices.L.map(row => matrices.C[0].map((_, j) => row.reduce((sum, value, k) => sum + value * matrices.C[k][j], 0)))
  const modes = eigenvalues(product).sort((a, b) => a - b).map(value => ({
    delay_s: Math.sqrt(value), velocity_m_s: length / Math.sqrt(value), max_section_length_m: length / Math.sqrt(value) * edge / 10,
    required_sections: Math.ceil(Math.sqrt(value) / edge * 10),
  }))
  const evidence = { name, corner: 'typ', request_file: requestFile, request_sha256: digest(JSON.stringify(request)),
    edges, length_m: length, matrices, modes, required_sections: Math.max(...modes.map(mode => mode.required_sections)) }
  cases[name] = { deck, matrices, evidence }
  await writeFile(`${root}/${name}-edge.json`, JSON.stringify(evidence, null, 2) + '\n')
}

async function run(name, label, sections, options = {}) {
  const directory = `${root}/${name}-${label}`
  await mkdir(directory, { recursive: true })
  let deck = cases[name].deck.replace(/\.subckt CHANNEL .*?\.ends CHANNEL/s, options.channel ?? channelSpice([cases[name].matrices], sections))
  if (options.end || options.start) deck = deck.replace(/^tran (\S+) (\S+) \S+ (\S+)/m, (_, step, end, max) => `tran ${step} ${options.end ?? end} ${options.start ?? 0} ${max}`)
  if (options.probes) deck = deck.replace(/^wrdata waveform.dat .*/m, `wrdata waveform.dat ${options.probes}`)
  if (options.maxord) deck = deck.replace('maxord=1', `maxord=${options.maxord}`)
  await writeFile(`${directory}/simulation.cir`, deck)
  const started = Date.now()
  let status = 'completed'
  let stdout = ''
  let stderr = ''
  try {
    const output = await exec('/opt/homebrew/bin/ngspice', ['-n', '-b', 'simulation.cir'], { cwd: directory, timeout, maxBuffer: 64 * 1024 * 1024 })
    stdout = output.stdout
    stderr = output.stderr
  } catch (error) {
    status = error.killed && error.signal === 'SIGTERM' && error.code === null ? 'timeout' : 'failed'
    stdout = error.stdout ?? ''
    stderr = error.stderr ?? ''
  }
  const last = [...(stdout + stderr).matchAll(/Reference value\s*:\s*(\S+)/g)].at(-1)?.[1]
  const result = { status, seconds: (Date.now() - started) / 1000, timeout_ms: timeout, deck_sha256: digest(deck),
    command: '/opt/homebrew/bin/ngspice -n -b simulation.cir', ...(last ? { last_reported_time_s: Number(last) } : {}) }
  await writeFile(`${directory}/stdout.log`, stdout)
  await writeFile(`${directory}/stderr.log`, stderr)
  await writeFile(`${directory}/result.json`, JSON.stringify(result, null, 2) + '\n')
  console.log(name, label, result)
  return directory
}

async function rows(directory) {
  return (await readFile(`${directory}/waveform.dat`, 'utf8')).trim().split('\n').slice(1).map(line => line.trim().split(/\s+/).map(Number))
}

async function compare(first, last, gate, baseline) {
  try {
    const a = await rows(first)
    const b = await rows(last)
    const start = Math.max(gate, a[0][0], b[0][0])
    const result = waveformConvergence(a, b, start, baseline ?? a[0].slice(1))
    result.probes.forEach((probe, i) => Object.assign(probe, {
      before_range_v: a.reduce(([min, max], row) => [Math.min(min, row[i + 1]), Math.max(max, row[i + 1])], [Infinity, -Infinity]),
      after_range_v: b.reduce(([min, max], row) => [Math.min(min, row[i + 1]), Math.max(max, row[i + 1])], [Infinity, -Infinity]),
    }))
    await writeFile(`${last}/comparison.json`, JSON.stringify({ gate_s: start, end_s: b.at(-1)[0], ...result }, null, 2) + '\n')
    console.log('comparison', result)
  } catch (error) {
    console.log('comparison unavailable:', error.message)
  }
}

if (phase === 'ladder' || phase === 'gear') {
  const count = cases.single.evidence.required_sections
  const first = await run('single', `${phase}-${count}`, count, { start: 8e-7, ...(phase === 'gear' ? { maxord: 2 } : {}) })
  const last = await run('single', `${phase}-${count * 2}`, count * 2, { start: 8e-7, ...(phase === 'gear' ? { maxord: 2 } : {}) })
  await compare(first, last, 8e-7, [3.3])
}
if (phase === 'nodes') {
  const paths = []
  for (const count of [4, 8]) paths.push(await run('single', `nodes-${count}`, count, {
    start: 3.49e-7, end: 3.6e-7, probes: `v(n2) v(xibis0.pkgl0) v(xibis0.pkgl1) v(xibis0.pkgl2) ${[1, 2, 3].map(i => `v(xchan.n${i * count / 4}_0)`).join(' ')} v(n4) v(xibis1.pkgl0) v(xibis1.pkgl1)`,
  }))
  await compare(paths[0], paths[1], 3.49e-7)
}
if (phase === 'package') {
  const original = cases.single.deck
  for (const variant of ['bounded-coefficients', 'ideal-die-rails']) {
    // Deliberately nonphysical A/B diagnostics, never adopted into the pipeline.
    cases.single.deck = variant === 'bounded-coefficients'
      ? original.replace(/^(VK[UD]\d+ .*?PWL\()(.*)(\))$/gm, (_, a, b, c) => a + b.split(/\s+/).map((value, i) => i % 2 ? String(Math.min(1, Math.max(0, Number(value)))) : value).join(' ') + c)
      : original.replace(/^[RL]PKG[12] .*\n/gm, '').replace(/^(\.subckt IBIS\d+_\S+ PAD0 REF0 REF1)$/gm, '$1\nVPGND REF0 PKGL1 0\nVPPOWER REF1 PKGL2 0')
    const paths = []
    for (const count of [4, 8]) paths.push(await run('single', `${variant}-${count}`, count, {
      start: 3.49e-7, end: 3.6e-7, probes: 'v(n2) v(n4) v(xibis0.pkgl1) v(xibis0.pkgl2)',
    }))
    await compare(paths[0], paths[1], 3.49e-7)
  }
}
if (phase === 'distributed') for (const name of ['single', 'differential', 'three']) {
  const { matrices: m } = cases[name]
  const n = m.R.length
  const ins = Array.from({ length: n }, (_, i) => `IN${i}`)
  const outs = Array.from({ length: n }, (_, i) => `OUT${i}`)
  const triangular = matrix => matrix.flatMap((row, i) => row.slice(i)).join(' ')
  const channel = n === 1
    ? `.subckt CHANNEL IN0 OUT0 REF\nO1 IN0 REF OUT0 REF LINE\n.model LINE LTRA R=${m.R[0][0]} L=${m.L[0][0]} C=${m.C[0][0]} G=0 LEN=1\n.ends CHANNEL`
    : `.subckt CHANNEL ${ins.join(' ')} ${outs.join(' ')} REF\nP1 ${ins.join(' ')} REF ${outs.join(' ')} REF LINE\n.model LINE CPL length=1\n+ R=${triangular(m.R)}\n+ L=${triangular(m.L)}\n+ C=${triangular(m.C)}\n+ G=${triangular(m.R.map(row => row.map(() => 0)))}\n.ends CHANNEL`
  const path = await run(name, 'distributed', 1, { channel, ...(name === 'three' ? { end: 8.1e-7 } : {}) })
  if (name === 'differential') await compare(`${input}/differential/native-6-ngspice`, path, 64e-6, [0])
}
